9		"entire.io/entire/git-sync/internal/validation"
10		"github.com/go-git/go-git/v6/plumbing"
11	)
12	
13	// RefKind distinguishes ref namespaces: branch, tag, or other (notes/pulls/custom).
14	type RefKind string
15	
16	const (
17		RefKindBranch RefKind = "branch"
18		RefKindTag    RefKind = "tag"
19		RefKindOther  RefKind = "other"
20	)
21	
22	// Action represents the planned operation on a ref.
23	type Action string
24	
25	const (
26		ActionCreate Action = "create"
27		ActionUpdate Action = "update"
28		ActionDelete Action = "delete"
29		ActionSkip   Action = "skip"
30		ActionBlock  Action = "block"
31		// ActionWarn is set when the target rejected an individual ref under
32		// best-effort policy; the server's reason is carried in BranchPlan.Reason.
33		ActionWarn Action = "warn"
34	)
35	
36	// RefMapping is a user-specified source:target mapping.
37	type RefMapping = validation.RefMapping
38	
39	// DesiredRef represents a source ref that should be mirrored to a target ref.
40	type DesiredRef struct {
41		Kind       RefKind
42		Label      string
43		SourceRef  plumbing.ReferenceName
44		TargetRef  plumbing.ReferenceName
45		SourceHash plumbing.Hash
46	}
47	
48	// ManagedTarget tracks which target refs are managed by git-sync.
49	type ManagedTarget struct {
50		Kind  RefKind
51		Label string
52	}
53	
54	// BranchPlan describes the planned action for a single ref.
55	type BranchPlan struct {
56		Branch     string                 `json:"branch"`
57		SourceRef  plumbing.ReferenceName `json:"sourceRef"`
58		TargetRef  plumbing.ReferenceName `json:"targetRef"`
59		SourceHash plumbing.Hash          `json:"sourceHash"`
60		TargetHash plumbing.Hash          `json:"targetHash"`
61		Kind       RefKind                `json:"kind"`
62		Action     Action                 `json:"action"`
63		Reason     string                 `json:"reason"`
64	}
65	
66	func (p BranchPlan) MarshalJSON() ([]byte, error) {
67		type bp struct {
68			Branch     string  `json:"branch"`
69			SourceRef  string  `json:"sourceRef"`
70			TargetRef  string  `json:"targetRef"`
71			SourceHash string  `json:"sourceHash"`
72			TargetHash string  `json:"targetHash"`
73			Kind       RefKind `json:"kind"`
74			Action     Action  `json:"action"`
75			Reason     string  `json:"reason"`
76		}
77		data, err := json.Marshal(bp{
78			Branch:     p.Branch,
79			SourceRef:  p.SourceRef.String(),
80			TargetRef:  p.TargetRef.String(),
81			SourceHash: p.SourceHash.String(),
82			TargetHash: p.TargetHash.String(),
83			Kind:       p.Kind,
84			Action:     p.Action,
85			Reason:     p.Reason,
86		})
87		if err != nil {
88			return nil, fmt.Errorf("marshal branch plan: %w", err)
89		}
90		return data, nil
91	}
92	
93	// ShortHash returns the first 8 characters of a hash, or "<zero>" for zero hashes.
94	func ShortHash(hash plumbing.Hash) string {
95		if hash.IsZero() {
96			return "<zero>"
97		}
98		s := hash.String()
99		if len(s) > 8 {
100			return s[:8]
101		}
102		return s
103	}
104	
105	// IsRefExcluded reports whether name matches any of the exclude prefixes.
106	// Empty prefixes are ignored. Used to subtract specific namespaces from
107	// auto-discovery (e.g. refs/pull/* under --all-refs against GitHub).
108	func IsRefExcluded(name plumbing.ReferenceName, excludePrefixes, excludeExact []string) bool {
109		if len(excludePrefixes) == 0 && len(excludeExact) == 0 {
110			return false
111		}
112		s := name.String()
113		for _, p := range excludePrefixes {
114			p = strings.TrimSpace(p)
115			if p == "" {
116				continue
117			}
118			if strings.HasPrefix(s, p) {
119				return true
120			}
121		}
122		// Exact names match the whole ref, so a caller can reserve
123		// refs/heads/entire without also excluding refs/heads/entire/foo — which
124		// a prefix cannot express (it would also catch refs/heads/entirely).
125		for _, e := range excludeExact {
126			if e = strings.TrimSpace(e); e != "" && s == e {
127				return true
128			}
129		}
130		return false
131	}
132	
133	// RefKindFromName infers the ref kind from a fully qualified ref name.
134	// Returns RefKindOther for any refs/* outside refs/heads/ and refs/tags/,
135	// and "" for names that don't start with refs/ at all.
136	func RefKindFromName(name plumbing.ReferenceName) RefKind {
137		switch {
138		case name.IsBranch():
139			return RefKindBranch
140		case name.IsTag():
141			return RefKindTag
142		case strings.HasPrefix(name.String(), "refs/"):
143			return RefKindOther
144		default:
145			return ""
146		}
147	}
148	
149	// ActionForTargetHash returns ActionCreate for zero hashes, ActionUpdate otherwise.
150	func ActionForTargetHash(hash plumbing.Hash) Action {
151		if hash.IsZero() {
152			return ActionCreate
153		}
154		return ActionUpdate
155	}
156	
157	// BranchMapFromRefHashMap extracts short branch names from a ref hash map.
158	func BranchMapFromRefHashMap(refs map[plumbing.ReferenceName]plumbing.Hash) map[string]plumbing.Hash {
159		branches := make(map[string]plumbing.Hash)
160		for name, hash := range refs {
161			if name.IsBranch() {
162				branches[name.Short()] = hash
163			}
164		}
165		return branches
166	}
167	
168	// SelectBranches filters branches to only the requested ones.
169	// If requested is empty, returns all.
170	func SelectBranches(source map[string]plumbing.Hash, requested []string) map[string]plumbing.Hash {
171		if len(requested) == 0 {
172			return source
173		}
174		selected := make(map[string]plumbing.Hash, len(requested))
175		for _, branch := range requested {
176			if hash, ok := source[branch]; ok {
177				selected[branch] = hash
178			}
179		}
180		return selected
181	}
182	
183	// RefPrefixes computes the ref-prefix arguments for v2 ls-refs from cfg.
184	// Under AllRefs the result collapses to a single "refs/" prefix.
185	func RefPrefixes(cfg PlanConfig) []string {
186		if cfg.AllRefs {
187			return []string{"refs/"}
188		}
189		prefixSet := map[string]struct{}{}
190		if len(cfg.Mappings) > 0 {
191			for _, m := range cfg.Mappings {
192				src := strings.TrimSpace(m.Source)
193				switch {
194				case strings.HasPrefix(src, "refs/tags/"):
195					prefixSet["refs/tags/"] = struct{}{}
196				case strings.HasPrefix(src, "refs/heads/"):
197					prefixSet["refs/heads/"] = struct{}{}
198				case !strings.HasPrefix(src, "refs/"):
199					prefixSet["refs/heads/"] = struct{}{}
200				}
201			}
202		} else {
203			prefixSet["refs/heads/"] = struct{}{}
204		}
205		if cfg.IncludeTags {
206			prefixSet["refs/tags/"] = struct{}{}
207		}
208		prefixes := make([]string, 0, len(prefixSet))
209		for p := range prefixSet {
210			prefixes = append(prefixes, p)
211		}
212		sort.Strings(prefixes)
213		return prefixes
214	}
215	
216	// CopyRefHashMap returns a shallow copy of a ref hash map.
217	func CopyRefHashMap(input map[plumbing.ReferenceName]plumbing.Hash) map[plumbing.ReferenceName]plumbing.Hash {
218		out := make(map[plumbing.ReferenceName]plumbing.Hash, len(input))
219		for k, v := range input {
220			out[k] = v
221		}
222		return out
223	}
224	
225	// BootstrapTempRef returns the temporary ref name used during batched bootstrap.
226	func BootstrapTempRef(targetRef plumbing.ReferenceName) plumbing.ReferenceName {
227		return plumbing.ReferenceName("refs/gitsync/bootstrap/heads/" + targetRef.Short())
228	}
229	
230	// FormatPlanLine formats a single plan entry for human-readable output.
231	func FormatPlanLine(plan BranchPlan) string {
232		label := plan.Branch
233		if plan.TargetRef != "" {
234			label = plan.TargetRef.String()
235		}
236		line := fmt.Sprintf("%s %s", strings.ToUpper(string(plan.Action)), label)
237		if plan.Reason != "" {
238			line += " - " + plan.Reason
239		}
240		return line
241	}
