		"object_count", packObjectCount,
		"objects_sent", objectsSent,
		"total_objects_in_pack", totalObjects,
		"aborted_early", abortedEarly,
		"will_subdivide", subdivide && len(batch.chain) > 0,
		"error", pushErr.Error())
