// markSyncSpanResult records a failed sync on the mirror.sync span — except for
// a benign concurrent-ref race, which lost a compare-and-swap to a competing
// sync of the same repo and self-heals on the next delivery. A race is tagged
// entire.sync.raced (queryable, mirroring the mirror.consume carve-out) but left
// un-errored, so it never shows as a failed mirror.sync span or counts toward an
// error-rate query on this span — matching the outcome metric's nak+term
// numerator, which also excludes raced. Exhaustion is a delivery-count concept
// the syncer can't see; the consumer still escalates a race that burns through
// redelivery to an error on the parent mirror.consume span (see
// shouldMarkSpanError). The race check uses the raw error, not the
// redacted/classified one, so redactAuth flattening the chain can't defeat it.
func markSyncSpanResult(span trace.Span, classified, raw error) {
	if isConcurrentRefError(raw) {
		span.SetAttributes(attribute.Bool("entire.sync.raced", true))
		return
	}
	span.RecordError(classified)
	span.SetStatus(otelcodes.Error, "sync from github")
}

// kind returns the request's source kind, defaulting the zero value to
// github so pre-kind callers and tests keep their meaning.
func (r syncRequest) kind() gitjobs.SourceKind {
	if r.SourceKind == "" {
		return gitjobs.SourceKindGithub
	}
	return r.SourceKind
}

func (s *syncer) sourceURL(req syncRequest) string {
	if req.kind() == gitjobs.SourceKindEntireDB {
		// The job carries the full by-ID URL (validated at decode,
		// host-admitted by the consumer); nothing to compose.
		return req.SourceURL
	}
	return fmt.Sprintf("%s/%s/%s", s.sourceBaseURL, req.SourceOwner, req.SourceRepo)
}

// reportSyncSuccess records a completed sync's outcome: the log line, and for a
// converged empty pair the counter reason that says the placement healed.
//
// Extracted from sync() for one reason — nothing could test it there. The
// converged branch is the only reason this change exists, and it is invisible
// to the compiler and to every existing test: deleting it left the whole suite
// green, because the position still gets stamped by the ordinary success path
// (err == nil), so the only casualties were the counter and the log. Those are
// exactly the signal COR-1300 was filed to produce, and they would have gone
// quiet with nothing failing.
//
// Takes the span from ctx rather than as a parameter so a test can call it with
// a plain context and get a no-op span, matching the replicate-thunk seam
// recoverDefaultBranchRename already uses for the same reason.
func (s *syncer) reportSyncSuccess(ctx context.Context, result gitsync.SyncResult, req syncRequest) {
	if result.Execution.Converged {
		// Source asserted empty, target asserted empty, and git-sync
		// corroborated both in one session: converged with nothing to apply.
		// Reported as a real success rather than a no-op BECAUSE the coverage
		// is provable, which is what lets the completion carry a write
		// position — the thing that clears a resync flag on a repo that was
		// created and never pushed to.
		trace.SpanFromContext(ctx).SetAttributes(attribute.Bool("entire.sync.converged", true))
		s.metrics.recordEmptySource(ctx, emptyReasonConverged, req.SourceClusterParent)
		slog.InfoContext(ctx, "Sync complete: source and target both empty, nothing to mirror",
			slog.String("source_owner", req.SourceOwner),
			slog.String("source_repo", req.SourceRepo),
			slog.String("target_ulid", req.TargetULID),
		)
		return
	}
	slog.InfoContext(ctx, "Sync complete",
		slog.String("source_owner", req.SourceOwner),
		slog.String("source_repo", req.SourceRepo),
		slog.String("target_ulid", req.TargetULID),
		slog.Int("applied", result.Counts.Applied),
		slog.Int("skipped", result.Counts.Skipped),
		slog.Int("blocked", result.Counts.Blocked),
		slog.Int("deleted", result.Counts.Deleted),
	)
}

	SourceHEAD    string    `json:"sourceHead,omitempty"`
	// SourceHeadUnborn reports that the source described HEAD as unborn — its
	// target branch does not exist. Diagnostic only: git emits that line for
	// any dangling HEAD, so it is never on its own evidence that a repository
	// is empty. It answers "did the source say anything about an unborn HEAD",
	// which is what distinguishes a source that cannot report one (protocol
	// v1, or a v2 server not advertising ls-refs=unborn) from one that did not.
	SourceHeadUnborn bool        `json:"sourceHeadUnborn"`
	Stats            Stats       `json:"stats"`
	Measurement      Measurement `json:"measurement"`
}

// SyncCounts tallies per-ref outcomes of a sync.
type SyncCounts struct {
	Applied int `json:"applied"`
	Skipped int `json:"skipped"`
	Blocked int `json:"blocked"`
	Deleted int `json:"deleted"`
	Warned  int `json:"warned"`
}

// BatchSummary reports batched push progress.
type BatchSummary struct {
	Enabled bool `json:"enabled"`
	Planned int  `json:"planned"`
	Done    int  `json:"done"`
}

// ExecutionSummary describes how a sync was executed.
type ExecutionSummary struct {
	DryRun             bool         `json:"dryRun"`
	Protocol           string       `json:"protocol"`
	OperationMode      string       `json:"operationMode"`
	Relay              bool         `json:"relay"`
	TransferMode       string       `json:"transferMode"`
	Reason             string       `json:"reason"`
	BootstrapSuggested bool         `json:"bootstrapSuggested"`
	SourceHEAD         string       `json:"sourceHead,omitempty"`
	Batch              BatchSummary `json:"batch"`
	// Converged reports that this run applied nothing because the source was
	// confirmed to have no refs and the target had none either — the two
	// already agree. Only ever set under SyncPolicy.AllowEmptySource, and it
	// is what distinguishes that converged state from an ordinary sync that
	// happened to have no work to do.
	//
	// It requires BOTH sides verified, so it is false in every other
	// empty-source outcome, including ErrSourceEmptyTargetPopulated where the
	// source was verified empty but the two have diverged. Emitted
	// unconditionally so "false" is distinguishable from a caller running a
	// build that predates the field.
	Converged bool `json:"converged"`
}

// SyncResult is the outcome of a Sync or Replicate.
type SyncResult struct {
	Refs        []RefResult      `json:"refs"`
	Counts      SyncCounts       `json:"counts"`
	Execution   ExecutionSummary `json:"execution"`
	Stats       Stats            `json:"stats"`
	Measurement Measurement      `json:"measurement"`
}

// PlanResult is the outcome of a Plan; it has the same shape as SyncResult.
type PlanResult = SyncResult

func fromProbeResult(result syncer.ProbeResult) ProbeResult {
	out := ProbeResult{
		SourceURL:        result.SourceURL,
		TargetURL:        result.TargetURL,
		RequestedMode:    result.RequestedMode,
		Protocol:         result.Protocol,
		RefPrefixes:      append([]string(nil), result.RefPrefixes...),
		Capabilities:     append([]string(nil), result.Capabilities...),
		TargetCaps:       append([]string(nil), result.TargetCaps...),
		Refs:             make([]RefInfo, 0, len(result.Refs)),
		SourceHEAD:       result.SourceHEAD.String(),
		SourceHeadUnborn: result.SourceHeadUnborn,
		Stats:            fromStats(result.Stats),
		Measurement:      fromMeasurement(result.Measurement),
	}
	for _, ref := range result.Refs {
		out.Refs = append(out.Refs, RefInfo{Name: ref.Name, Hash: ref.Hash.String()})
	}
	return out
}

func fromSyncResult(result syncer.Result) SyncResult {
	out := SyncResult{
		Refs: make([]RefResult, 0, len(result.Plans)),
		Counts: SyncCounts{
			Applied: result.Pushed,
			Skipped: result.Skipped,
			Blocked: result.Blocked,
			Deleted: result.Deleted,
			Warned:  result.Warned,
		},
		Execution: ExecutionSummary{
			DryRun:             result.DryRun,
			Protocol:           result.Protocol,
			OperationMode:      result.OperationMode,
			Relay:              result.Relay,
			TransferMode:       result.RelayMode,
			Reason:             result.RelayReason,
			BootstrapSuggested: result.BootstrapSuggested,
			SourceHEAD:         result.SourceHEAD.String(),
			Converged:          result.Converged,
			Batch: BatchSummary{
				Enabled: result.Batching,
				Planned: result.PlannedBatchCount,
				Done:    result.BatchCount,
			},
		},
		Stats:       fromStats(result.Stats),
		Measurement: fromMeasurement(result.Measurement),
	}
	for _, plan := range result.Plans {
		out.Refs = append(out.Refs, RefResult{
			Branch:     plan.Branch,
			SourceRef:  plan.SourceRef.String(),
			TargetRef:  plan.TargetRef.String(),
			SourceHash: hashString(plan.SourceHash),
			TargetHash: hashString(plan.TargetHash),
			Kind:       RefKind(plan.Kind),
			Action:     Action(plan.Action),
			Reason:     plan.Reason,
		})
	}
	return out
}

