1	package planner
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7	
8		"entire.io/entire/git-sync/internal/validation"
9		"github.com/go-git/go-git/v6/plumbing"
10		"github.com/go-git/go-git/v6/plumbing/object"
11		"github.com/go-git/go-git/v6/plumbing/storer"
12	)
13	
14	// PlanConfig holds configuration for plan generation.
15	type PlanConfig struct {
16		Branches    []string
17		Mappings    []RefMapping
18		IncludeTags bool
19		Force       bool
20		Prune       bool
21		// AllRefs broadens the desired set to every refs/* on the source
22		// (notes, pulls, replace, custom namespaces) in addition to whatever
23		// branches/tags the existing flags select. Mappings can rename refs
24		// in any namespace when AllRefs is set; otherwise only refs/heads/
25		// and refs/tags/ are accepted.
26		AllRefs bool
27		// ExcludeRefPrefixes subtracts namespaces from auto-discovery. A ref
28		// whose name starts with any of these prefixes is not pulled, pushed,
29		// or pruned. Explicit Mappings are not subject to this filter.
30		ExcludeRefPrefixes []string
31		// ExcludeRefs subtracts exact ref names (whole-name match) from
32		// auto-discovery, same effect as ExcludeRefPrefixes but without matching
33		// children — so a caller can reserve refs/heads/entire while still
34		// mirroring refs/heads/entire/foo. Explicit Mappings are not subject to it.
35		ExcludeRefs []string
36	}
37	
38	// BuildDesiredRefs constructs the set of desired refs and managed targets from
39	// source refs and user configuration. All mapping validation happens here,
40	// before any network activity (issue #2, #3).
41	func BuildDesiredRefs(
42		sourceRefs map[plumbing.ReferenceName]plumbing.Hash,
43		cfg PlanConfig,
44	) (map[plumbing.ReferenceName]DesiredRef, map[plumbing.ReferenceName]ManagedTarget, error) {
45		cfg = normalizeAllRefs(cfg)
46		desired := make(map[plumbing.ReferenceName]DesiredRef)
47		managed := make(map[plumbing.ReferenceName]ManagedTarget)
48	
49		addManaged := func(sourceRef, targetRef plumbing.ReferenceName, kind RefKind, hash plumbing.Hash) error {
50			if hash.IsZero() {
51				return fmt.Errorf("source ref %s not found", sourceRef)
52			}
53			// Reject duplicate target refs from different sources (issue #2, #3).
54			if existing, ok := desired[targetRef]; ok && existing.SourceRef != sourceRef {
55				return fmt.Errorf("duplicate target ref %s: mapped from both %s and %s", targetRef, existing.SourceRef, sourceRef)
56			}
57			short := targetRef.Short()
58			desired[targetRef] = DesiredRef{
59				Kind:       kind,
60				Label:      short,
61				SourceRef:  sourceRef,
62				TargetRef:  targetRef,
63				SourceHash: hash,
64			}
65			managed[targetRef] = ManagedTarget{Kind: kind, Label: short}
66			return nil
67		}
68	
69		if len(cfg.Mappings) > 0 {
70			// Validate all mappings up front (issue #2, #3)
71			normalized, err := validation.ValidateMappings(cfg.Mappings, cfg.AllRefs)
72			if err != nil {
73				return nil, nil, fmt.Errorf("validate ref mappings: %w", err)
74			}
75			for _, nm := range normalized {
76				kind := RefKindFromName(nm.TargetRef)
77				if err := addManaged(nm.SourceRef, nm.TargetRef, kind, sourceRefs[nm.SourceRef]); err != nil {
78					return nil, nil, err
79				}
80			}
81		} else {
82			branches := BranchMapFromRefHashMap(sourceRefs)
83			selected := SelectBranches(branches, cfg.Branches)
84			for branch, hash := range selected {
85				refName := plumbing.NewBranchReferenceName(branch)
86				if IsRefExcluded(refName, cfg.ExcludeRefPrefixes, cfg.ExcludeRefs) {
87					continue
88				}
89				if err := addManaged(refName, refName, RefKindBranch, hash); err != nil {
90					return nil, nil, err
91				}
92			}
93		}
94	
95		// AllRefs implies tag inclusion. Both passes (tag, other-kind) walk
96		// sourceRefs once: under AllRefs+IncludeTags this saves a redundant
97		// iteration on repos with thousands of refs/changes/* or refs/notes/*.
98		wantTags := cfg.IncludeTags || cfg.AllRefs
99		if wantTags || cfg.AllRefs {
100			for refName, hash := range sourceRefs {
101				kind := RefKindFromName(refName)
102				switch {
103				case kind == RefKindTag && wantTags:
104				case kind == RefKindOther && cfg.AllRefs:
105				default:
106					continue
107				}
108				if IsRefExcluded(refName, cfg.ExcludeRefPrefixes, cfg.ExcludeRefs) {
109					continue
110				}
111				if _, ok := desired[refName]; ok {
112					continue
113				}
114				if err := addManaged(refName, refName, kind, hash); err != nil {
115					return nil, nil, err
116				}
117			}
118		}
119	
120		return desired, managed, nil
121	}
122	
123	// normalizeAllRefs zeros Branches under AllRefs so the desired-set and
124	// prune predicates agree on scope.
125	func normalizeAllRefs(cfg PlanConfig) PlanConfig {
126		if cfg.AllRefs {
127			cfg.Branches = nil
128		}
129		return cfg
130	}
131	
132	// BuildPlans generates the action plans for each managed ref.
133	func BuildPlans(
134		store storer.EncodedObjectStorer,
135		desired map[plumbing.ReferenceName]DesiredRef,
136		targetRefs map[plumbing.ReferenceName]plumbing.Hash,
137		managed map[plumbing.ReferenceName]ManagedTarget,
138		cfg PlanConfig,
139	) ([]BranchPlan, error) {
140		cfg = normalizeAllRefs(cfg)
141		if cfg.Prune {
142			// addPruneCandidates mutates the map, so copy first — the caller's
143			// managed map must not be modified (matches BuildReplicationPlans).
144			managed = copyManagedTargets(managed)
145			addPruneCandidates(managed, targetRefs, cfg)
146		}
147	
148		targetNames := make([]plumbing.ReferenceName, 0, len(managed))
