package syncer

import (
	"context"
	"testing"

	"entire.io/entire/git-sync/internal/planner"
	"entire.io/entire/git-sync/internal/syncertest"
	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
	"github.com/go-git/go-git/v6/storage/memory"
)

// Probe: batched bootstrap + BestEffort + rejected branch create.
func TestZZProbeBatchedCutoverLosesMarker(t *testing.T) {
	sourceRepo, sourceFS := newSourceRepo(t)
	makeLargeCommits(t, sourceRepo, sourceFS, 80, 5_000)

	targetRepo, err := git.Init(memory.NewStorage())
	if err != nil {
		t.Fatalf("init target: %v", err)
	}
	sourceServer := newSmartHTTPRepoServerV2(t, sourceRepo)
	targetServer := newSmartHTTPRepoServer(t, targetRepo)
	defer sourceServer.Close()
	defer targetServer.Close()

	branchRef := plumbing.NewBranchReferenceName(testBranch)
	tempRef := planner.BootstrapTempRef(branchRef)

	// Simulate a receive-pack that accepts everything but the branch create:
	// apply the other commands by hand (a returned report short-circuits the
	// server before it applies anything), then report ng for the branch.
	targetServer.receivePackHook = func(req *packp.UpdateRequests, _ bool) *packp.ReportStatus {
		denied := false
		for _, cmd := range req.Commands {
			if cmd.Name == branchRef {
				denied = true
				continue
			}
			if cmd.New.IsZero() {
				_ = targetRepo.Storer.RemoveReference(cmd.Name)
			} else {
				_ = targetRepo.Storer.SetReference(plumbing.NewHashReference(cmd.Name, cmd.New))
			}
		}
		if !denied {
			return syncertest.DenyRefsReport(req) // all-ok report
		}
		return syncertest.DenyRefsReport(req, "deny creating a protected branch", branchRef)
	}

	result, err := Bootstrap(context.Background(), Config{
		Source:             Endpoint{URL: sourceServer.RepoURL()},
		Target:             Endpoint{URL: targetServer.RepoURL()},
		AllRefs:            true,
		BestEffort:         true,
		ProtocolMode:       protocolModeAuto,
		TargetMaxPackBytes: 350_000,
	})
	branchPresent := false
	if _, e := targetRepo.Reference(branchRef, true); e == nil {
		branchPresent = true
	}
	markerPresent := false
	markerHash := plumbing.ZeroHash
	if r, e := targetRepo.Reference(tempRef, true); e == nil {
		markerPresent, markerHash = true, r.Hash()
	}
	t.Logf("PROBE err=%v relayMode=%q batching=%t batches=%d", err, result.RelayMode, result.Batching, result.BatchCount)
	t.Logf("PROBE after run: branch present=%t  marker present=%t (%s)", branchPresent, markerPresent, planner.ShortHash(markerHash))
	if err == nil && !branchPresent && !markerPresent {
		t.Log("PROBE CONFIRMED: success reported, branch absent, resume position destroyed")
	}
