// mirror-pipeline-admin is an operator CLI for the mirror pipeline. It talks to
// the same external systems the services do, for one-off administrative tasks
// that don't belong in a long-running binary.
//
// Commands are grouped by the component they act on:
//
//	webhooks    GitHub App webhook deliveries (list failures, redeliver) and the
//	            captured-delivery DLQ (list, get, replay)
//	failindex   the mirror-sync failure-index KV (list, get, delete)
//	backfill    the meta-fanout backfill work-queues (status, purge-orphans)
//
// Authentication differs by group. The webhooks GitHub-App subcommands
// (list-failed, redeliver) use a GitHub App JWT (see githubapp.go): the App
// credentials are NOT a mirror-pipeline secret — the services mint repo tokens
// via entire-core — so the operator supplies the App id + private key (from
// 1Password) via flags or env (docs/runbooks/webhook-redelivery.md). The NATS
// subcommands (webhooks dlq, failindex) authenticate via mTLS using the
// ENTIRE_INTERNAL_TLS_{CERT,KEY,CA}_FILE triple (see nats.go); region matters —
// failindex is per-cluster, the DLQ + replay are US-only
// (docs/runbooks/webhook-dlq.md).
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/signal"

	"github.com/entirehq/mirror-pipeline/internal/version"
)

func main() {
	slog.SetDefault(slog.New(slog.NewTextHandler(os.Stderr, nil)))
	if err := run(); err != nil {
		if errors.Is(err, context.Canceled) {
			slog.Warn("interrupted")
			os.Exit(130)
		}
		slog.Error("mirror-pipeline-admin failed", slog.Any("error", err))
		os.Exit(1)
	}
}

func run() error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	if len(os.Args) < 2 {
		usage()
		return errors.New("a command is required")
	}

	switch os.Args[1] {
	case "webhooks":
		return runWebhooks(ctx, os.Args[2:])
	case "failindex":
		return runFailindex(ctx, os.Args[2:])
	case "backfill":
