package main

import (
	"context"
	"flag"
	"fmt"
	"log/slog"

	"github.com/entirehq/mirror-pipeline/pkg/failindex"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// rekickReasonAll selects every reason for a bulk re-kick.
const rekickReasonAll = "all"

// rekickTarget is one entry to re-emit.
type rekickTarget struct {
	ulid string
	fs   failindex.FailedSync
}

// rekickIndex is the read surface rekick needs from the failure index — a seam so
// the candidate selection is unit-testable without a live NATS (*failindex.Index
// satisfies it; mirrors cmd/rekicker's failIndexReader).
type rekickIndex interface {
	Keys(ctx context.Context) ([]string, error)
	Get(ulid string) (failindex.FailedSync, bool, error)
}

// runFailindexRekick re-emits stored jobs from the failure index back onto their
// mirror_git_v1 subject, the same mechanism cmd/rekicker uses — but for the
// reason class the automated re-kicker deliberately skips: permanent. The
// automated re-kicker won't re-drive permanents because they re-fail identically
// every tick (a revoked install, a gone repo, an expired token). Once an operator
// has FIXED the root cause, this command re-drives them once so they re-sync and
// self-clear via the worker's clear-on-success path. Reasons the automated
// re-kicker already handles (max_deliveries, validation) are reachable too via
// --reason, but rarely needed.
func runFailindexRekick(ctx context.Context, args []string) error {
	fs := flag.NewFlagSet("failindex rekick", flag.ContinueOnError)
	natsURL := natsURLFlag(fs)
	bucket := bucketFlag(fs)
	reason := fs.String("reason", string(failindex.ReasonPermanent),
		"re-kick entries with this reason: permanent|max_deliveries|validation|all (ignored when --ulid is set)")
	ulid := fs.String("ulid", "", "re-kick exactly this entry, regardless of reason")
	live := fs.Bool("live", false, "actually re-publish the jobs (default: dry-run, prints a sample and exits)")
	rate := fs.Float64("rate", 10, "target re-kicks/sec")
	limit := fs.Int("limit", 0, "stop after this many entries (0 = no limit)")
	if err := fs.Parse(args); err != nil {
		return helpOrErr(err)
	}
	if err := validateRekickReason(*reason); err != nil {
		return err
	}

	idx, js, nc, err := openFailIndex(*natsURL, *bucket)
	if err != nil {
		return err
	}
	defer nc.Close()
