// handleAdminResumeMirror is POST /api/admin/mirrors/{id}/resume. Clears
// the suspended_at flag, re-arming the placement: lookups and fan-out
// that filter on suspended_at IS NULL see it again immediately.
// Suspensions are both operator-driven and webhook-driven (the App
// suspended in the GitHub UI, COR-853 — the removal webhooks tear down
// instead, COR-454); this tool lifts either, and is the documented
// recovery path when a webhook resume was lost (e.g. the resume job aged
// out at StreamMaxAge).
//
// mirror_repos lives in global cockroach, so a resume issued against any
// regional core is visible everywhere.
func (s *Server) handleAdminResumeMirror(w http.ResponseWriter, r *http.Request) {
	if !s.requirePlatformAdmin(w, r) {
		return
	}
	if s.mirrorRepos == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "mirror service not configured"})
		return
	}
	idStr := r.PathValue("id")
	id, err := model.ParseRepoID(idStr)
	if err != nil {
		http.Error(w, "bad request: invalid mirror repo ID", http.StatusBadRequest)
		return
	}
	if err := s.ResumeMirrorForce(r.Context(), id); err != nil {
		if errors.Is(err, mirrorrepo.ErrNotFound) {
			http.Error(w, "mirror not found", http.StatusNotFound)
			return
		}
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	caller := ClaimsFromContext(r.Context())
	slogutil.Info(r.Context(), "mirror resumed by admin",
		slog.String("repo_id", idStr),
		slog.String("admin_handle", caller.Handle),
		slog.String("admin_account_id", caller.AccountID.String()),
	)
	writeJSON(w, http.StatusOK, map[string]string{"resumed": idStr})
}

// ResumeMirror is the AUTOMATIC-resume entry point behind the repoops resume
// consumer (installation.unsuspend / re-add), and it satisfies repoops.Resumer.
// It re-arms a suspended placement and best-effort kicks it back into sync
// (re-publish a sync_repo, re-materialize grants from current GitHub truth) —
// UNLESS an operator hold is in place, in which case the placement stays
// suspended and this returns nil (nothing to do): an automatic resume must not
// undo a manual pause. Use ResumeMirrorForce for the operator override.
//
// The recipe itself lives in core/mirrorresume so this path and the periodic
// backstop sweep (COR-852) can't drift on the steps; this method is a thin
// delegate that assembles the recipe from the Server's deps.
//
// mirror_repos lives in global cockroach, so a resume issued against any
// regional core is visible everywhere. Returns mirrorrepo.ErrNotFound if the
// placement doesn't exist; callers map that to their own not-found response.
func (s *Server) ResumeMirror(ctx context.Context, id model.RepoID) error {
	// honorOperatorHold=true: leave a manual pause alone. githubRepoID 0: no
	// attachment gate is wired here (the repoops consumer runs its own
	// currentlyAttached check), so the gate — the only reader of that argument —
	// is never consulted. The ResumeOutcome is likewise irrelevant to this
	// facade's callers; the per-result accounting is the backstop sweep's concern.
	_, err := s.newMirrorResumer(ctx, true).ResumeMirror(ctx, id, 0)
	return err //nolint:wrapcheck // the Resumer wraps mirrorrepo.ErrNotFound with %w; callers errors.Is it.
}

// ResumeMirrorForce is the operator override behind the admin resume endpoint:
// it lifts a suspension unconditionally, INCLUDING an operator hold — a human
// resume is the one caller entitled to. Otherwise identical to ResumeMirror.
func (s *Server) ResumeMirrorForce(ctx context.Context, id model.RepoID) error {
	resumer := s.newMirrorResumer(ctx, false)
	_, err := resumer.ResumeMirror(ctx, id, 0)
	if errors.Is(err, mirrorresume.ErrGrantPreparationFailed) && !errors.Is(err, mirrorrepo.ErrNotFound) {
		// Preserve the historical admin override when live grant preparation is
		// unavailable or fails, but do not call the ordinary Resume: that would
		// restore repo#group inheritance from grants we cannot prove current. The
		// placement becomes active with direct grants blank and its group edge detached.
		slogutil.Warn(ctx, "mirror resume: live grant preparation failed; resuming without repo group access",
			slog.String("mirror_repo_id", id.String()), slog.Any("error", err))
		return resumer.ResumeMirrorWithoutGroupAccess(ctx, id) //nolint:wrapcheck // preserves mirrorrepo.ErrNotFound for the handler.
	}
	return err //nolint:wrapcheck // the Resumer wraps mirrorrepo.ErrNotFound with %w; callers errors.Is it.
}

// newMirrorResumer assembles the shared resume recipe from the Server's deps.
// Built per call so the lazily-constructed mirror-perms reconciler — which logs
// on construction failure — is resolved against the live ctx. Dependencies are
// wired only when present so the recipe's fail-closed checks see a true nil

