// kickResync re-publishes a sync_repo for the just-resumed placement. Resume
// reset status to 'processing'; this kick makes the worker re-confirm the clone
// so the completion advances status off 'processing'. Best-effort: every
// failure is logged and swallowed — the resume already succeeded and the data
// still exists, so the next organic webhook or freshness reconcile drives the
// sync if this kick does not land.
func (r *Resumer) kickResync(ctx context.Context, id model.RepoID) {
	if r.publisher == nil {
		slogutil.Warn(ctx, "mirror resume: no git-jobs publisher; skipping resync kick (status stays processing until next organic sync)",
			slog.String("mirror_repo_id", id.String()))
		return
	}
	// FRESH: this is a read-your-own-write immediately after Resume cleared
	// suspended_at, and the row it hydrates is the payload of the sync job
	// published below — a stale coord pair would aim the worker at the upstream's
	// pre-rename slug. Post-RBR it costs one cross-partition probe per resume,
	// and resumes are admin actions or cron-sweep ticks, not user requests, so
	// there is nothing here worth trading correctness for.
	rows, err := r.placements.ListRowsByIDs(ctx, []model.RepoID{id})
	if err != nil || len(rows) == 0 {
		slogutil.Warn(ctx, "mirror resume: could not load placement for resync kick; status stays processing until next organic sync",
			slog.String("mirror_repo_id", id.String()), slog.Any("error", err))
		return
	}
	row := rows[0]
	var installationID int64
	if row.InstallationID != nil {
		installationID = *row.InstallationID
	}
	if err := r.publisher.PublishSyncRepo(ctx,
		gitjobs.Placement{Jurisdiction: row.Jurisdiction, ClusterID: row.ClusterSlug},
		gitjobs.Source{
			Owner:   row.OwnerLogin,
			Repo:    row.RepoName,
			AuthRef: gitjobs.FormatGithubInstallationAuthRef(installationID),
		},
		gitjobs.Target{ULID: id.String()},
	); err != nil {
		slogutil.Error(ctx, "mirror resume: resync kick publish failed; status stays processing until next organic sync",
			slog.String("mirror_repo_id", id.String()),
			slog.String("jurisdiction", row.Jurisdiction),
			slog.String("cluster_slug", row.ClusterSlug),
			slog.Any("error", err))
	}
}

// reconcileGroupBeforeResume refreshes GitHub truth and converges the shared
// group while the placement is still suspended and its repo#group edge remains
// detached. SuspendedError intentionally carries the coordinates needed for
// this pre-resume snapshot.
func (r *Resumer) reconcileGroupBeforeResume(ctx context.Context, id model.RepoID) (int64, error) {
	ref, err := r.placements.GetRefByID(ctx, id)
	if err != nil {
		var suspended *mirrorrepo.SuspendedError
		if !errors.As(err, &suspended) {
			return 0, fmt.Errorf("load ref for collaborator refresh: %w", err)
		}
		ref = &suspended.Ref
	}
	// Resolve existence before checking optional wiring so every configuration
	// preserves mirrorrepo.ErrNotFound for callers that dispose missing rows.
	if r.refresher == nil {
		return 0, errors.New("collaborator refresher unavailable")
	}
	if r.reconciler == nil {
		return 0, errors.New("grant reconciler unavailable")

