package cli

import (
	"github.com/spf13/cobra"

	"entire.io/client/contexts"
)

// newContextCmd builds the `entire-core context` subtree. Context
// management (login, listing, switching) now lives in the public
// `entire` CLI (github.com/entireio/cli); these subcommands are kept
// only as deprecation stubs that point operators at the replacement.
//
// The `--context` root flag is NOT deprecated — it still selects a
// stored context for cross-region routing, reading the contexts.json
// that `entire login` writes. That's why completeContextNames /
// loadContextNames remain below.
func newContextCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "context",
		Short: "DEPRECATED — use `entire auth`",
		Long: "Context management moved to the public `entire` CLI. " +
			"Use `entire login`, `entire logout`, `entire auth contexts`, " +
			"and `entire auth use`.",
	}
	cmd.AddCommand(
		deprecatedCmd("list", "entire auth contexts"),
		deprecatedCmd("use NAME", "entire auth use <context>"),
		deprecatedCmd("bind HOST NAME", "entire auth use <context>"),
		deprecatedCmd("current", "entire auth contexts"),
	)
	return cmd
}

// completeContextNames offers stored context names as completions for the
// root `--context` flag. Returns NoFileComp so the shell doesn't fall back
// to listing files when the contexts file is missing or unreadable.
func completeContextNames(_ *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
	return loadContextNames(), cobra.ShellCompDirectiveNoFileComp
}

func loadContextNames() []string {
	configDir, err := entireConfigDir()
	if err != nil {
		return nil
	}
	f, err := contexts.Load(configDir)
	if err != nil || f == nil {
		return nil
	}
	names := make([]string, 0, len(f.Contexts))
	for _, c := range f.Contexts {
		names = append(names, c.Name)
	}
	return names
}
