// bottomOutParams builds a batched bootstrap over a single-commit chain, so
// checkpoint subdivision has nothing to split, with a pack big enough that the
// observer's aborter fires against budget.
func bottomOutParams(t *testing.T, budget, announced int64, packBytes int, pushes *int) Params {
	t.Helper()
	mainRef := plumbing.NewBranchReferenceName("main")
	hashes := makeLinearCommitChain(t, 1)
	body := append([]byte("PACK"), bytes.Repeat([]byte("x"), packBytes)...)

	return Params{
		SourceService: fakeBootstrapSource{
			fetchCommitParents: func(_ context.Context, _ gitproto.Conn, _ gitproto.DesiredRef, _ []plumbing.Hash) (map[plumbing.Hash][]plumbing.Hash, error) {
				store := memory.NewStorage()
				writeLinearCommitChain(t, store, 1)
				return parentsFromCommitChainStore(t, store), nil
			},
			// Fresh reader per attempt: the retry re-fetches.
			fetchPack: func(_ context.Context, _ gitproto.Conn, _ map[plumbing.ReferenceName]gitproto.DesiredRef, _ map[plumbing.ReferenceName]plumbing.Hash) (io.ReadCloser, error) {
				return io.NopCloser(bytes.NewReader(body)), nil
			},
		},
		TargetPusher: fakeBootstrapPusher{
			// Drain the observer so its byte counter advances and the aborter
			// can fire; the abort surfaces as the read error.
			pushPack: func(_ context.Context, _ []gitproto.PushCommand, pack io.ReadCloser) error {
				*pushes++
				_, err := io.Copy(io.Discard, pack)
				return err
			},
			pushCommands: func(_ context.Context, _ []gitproto.PushCommand) error { return nil },
		},
		DesiredRefs: map[plumbing.ReferenceName]planner.DesiredRef{
			mainRef: {
				SourceRef: mainRef, TargetRef: mainRef,
				SourceHash: hashes[len(hashes)-1], Kind: planner.RefKindBranch, Label: "main",
			},
		},
		TargetRefs:           map[plumbing.ReferenceName]plumbing.Hash{},
		TargetMaxPack:        budget,
		AnnouncedTargetLimit: announced,
	}
}

func TestExecuteBatchedSelfImposedAbortIsNotPermanent(t *testing.T) {
	// Our own budget stopped the upload and the target never stated a limit,
	// so we have no evidence it would refuse the pack. That must stay
	// retryable — permafailing here would strand a repo a larger budget or a
	// config change could still mirror.
	pushes := 0
	_, err := Execute(context.Background(), bottomOutParams(t, 64, 0, 4096, &pushes), "empty target")
	if err == nil {
		t.Fatal("expected the push to fail")
	}
	if errors.Is(err, ErrCheckpointExceedsTargetLimit) {
		t.Fatalf("self-imposed abort must not be classified permanent: %v", err)
	}
	if pushes != 1 {
		t.Fatalf("expected no relaxed retry without an announced limit, got %d pushes", pushes)
	}
}

func TestExecuteBatchedRetriesIndivisibleCheckpointAtAnnouncedLimit(t *testing.T) {
	// The whole point: subdivision has bottomed out at one commit and OUR
	// budget aborted the upload, but the target said it accepts far more. The
	// checkpoint is retried against the target's own limit and succeeds —
	// where before this the run failed outright.
	pushes := 0
	result, err := Execute(context.Background(), bottomOutParams(t, 64, 1<<20, 4096, &pushes), "empty target")
	if err != nil {
		t.Fatalf("expected the relaxed retry to converge, got %v", err)
	}
	if pushes != 2 {
		t.Fatalf("expected exactly one relaxed retry (2 pushes), got %d", pushes)
	}
	if !result.Batching {
		t.Fatalf("expected a batched result, got %+v", result)
	}
}

func TestExecuteBatchedPermanentOnceTargetsOwnLimitIsExceeded(t *testing.T) {
	// Retried at the announced limit and still projected past it: the verdict
	// is now the target's, not ours, and the checkpoint cannot be split. That
	// is terminal — redelivery would re-send the identical pack.
	pushes := 0
	_, err := Execute(context.Background(), bottomOutParams(t, 64, 256, 4096, &pushes), "empty target")
	if err == nil {
		t.Fatal("expected the push to fail")
	}
	if !errors.Is(err, ErrCheckpointExceedsTargetLimit) {
		t.Fatalf("expected ErrCheckpointExceedsTargetLimit, got %v", err)
	}
	if pushes != 2 {
		t.Fatalf("expected one relaxed retry before giving up, got %d pushes", pushes)
	}
}
